#!/usr/bin/python3

def verify_condition(f, p, k):
    for index in range(p):
        if f[(k * index) % p] != (k * f[index]) % p:
            return False
    return True

def count_configurations(f, p, k, position):
    if position == p:
        return verify_condition(f, p, k)
    total = 0
    for value in range(p):
        f.append(value)
        total += count_configurations(f, p, k, position + 1)
        f.pop()
    return total

def compute_result(p, k):
    total_groups = 0
    seen = set()
    for start in range(p):
        if start not in seen:
            total_groups += 1
        current = start
        while current not in seen:
            seen.add(current)
            current = (current * k) % p
    return pow(p, total_groups - (k != 1), 10 ** 9 + 7)

p, k = map(int, input().split())
print(compute_result(p, k))
